"use client";

import { useCallback, useMemo, useState } from "react";
import {
  Background,
  Controls,
  MiniMap,
  ReactFlow,
  addEdge,
  applyEdgeChanges,
  applyNodeChanges,
  type Connection,
  type Edge,
  type EdgeChange,
  type Node,
  type NodeChange,
  type OnConnect,
} from "@xyflow/react";

import SystemNode, {
  type SystemNodeData,
} from "./SystemNode";

import ConnectionModal, {
  type ConnectionData,
} from "./ConnectionModal";

import SystemModal from "./SystemModal";

import {
  initialSystems,
  initialConnections,
} from "./architecture/data";

import type {
  EngineeringSystem,
} from "./architecture/types";

type ArchitectureNode = Node<SystemNodeData>;
type ArchitectureEdge = Edge;

const initialPositions: Record<
  string,
  { x: number; y: number }
> = {
  orion: {
    x: 400,
    y: 250,
  },

  power: {
    x: 50,
    y: 100,
  },

  battery: {
    x: -300,
    y: 50,
  },

  bms: {
    x: -300,
    y: 180,
  },

  perception: {
    x: 400,
    y: 50,
  },

  camera: {
    x: 750,
    y: -50,
  },

  lidar: {
    x: 750,
    y: 80,
  },

  imu: {
    x: 750,
    y: 210,
  },

  computing: {
    x: 400,
    y: 450,
  },

  jetson: {
    x: 750,
    y: 400,
  },

  ai: {
    x: 750,
    y: 530,
  },

  control: {
    x: 50,
    y: 450,
  },
};

const initialNodes: ArchitectureNode[] =
  initialSystems.map((system) => ({
    id: system.id,
    type: "system",
    position:
      initialPositions[system.id] ?? {
        x: 0,
        y: 0,
      },
    data: {
      ...system,
    },
  }));

const initialEdges: ArchitectureEdge[] =
  initialConnections.map((connection) => ({
    id: connection.id,
    source: connection.sourceId,
    target: connection.targetId,
    label: connection.protocol
      ? `${connection.type} · ${connection.protocol}`
      : connection.type,
    data: {
      type: connection.type,
      protocol: connection.protocol,
      description: connection.description,
    },
  }));

export default function Architecture() {
  const [nodes, setNodes] =
    useState<ArchitectureNode[]>(initialNodes);

  const [edges, setEdges] =
    useState<ArchitectureEdge[]>(initialEdges);

  const [systemModalOpen, setSystemModalOpen] =
    useState(false);

  const [editingNodeId, setEditingNodeId] =
    useState<string | null>(null);

  const [connectionModalOpen, setConnectionModalOpen] =
    useState(false);

  const [pendingConnection, setPendingConnection] =
    useState<Connection | null>(null);

  /*
   * React Flow custom node types.
   */
  const nodeTypes = useMemo(
    () => ({
      system: SystemNode,
    }),
    []
  );

  /*
   * ---------------------------------------------------------
   * NODE CHANGES
   * ---------------------------------------------------------
   */
  const onNodesChange = useCallback(
    (changes: NodeChange[]) => {
      setNodes((current) =>
        applyNodeChanges(
          changes,
          current
        ) as ArchitectureNode[]
      );
    },
    []
  );

  /*
   * ---------------------------------------------------------
   * EDGE CHANGES
   * ---------------------------------------------------------
   */
  const onEdgesChange = useCallback(
    (changes: EdgeChange[]) => {
      setEdges((current) =>
        applyEdgeChanges(
          changes,
          current
        )
      );
    },
    []
  );

  /*
   * ---------------------------------------------------------
   * OPEN SYSTEM EDITOR
   * ---------------------------------------------------------
   */
  const openSystemEditor = useCallback(
    (nodeId: string) => {
      setEditingNodeId(nodeId);
      setSystemModalOpen(true);
    },
    []
  );

  /*
   * ---------------------------------------------------------
   * DELETE SYSTEM
   * ---------------------------------------------------------
   */
  const deleteSystem = useCallback(
    (nodeId: string) => {
      const node = nodes.find(
        (item) => item.id === nodeId
      );

      if (!node) {
        return;
      }

      const confirmed = window.confirm(
        `Delete "${node.data.name}"?`
      );

      if (!confirmed) {
        return;
      }

      setNodes((current) =>
        current.filter(
          (item) => item.id !== nodeId
        )
      );

      setEdges((current) =>
        current.filter(
          (edge) =>
            edge.source !== nodeId &&
            edge.target !== nodeId
        )
      );

      if (editingNodeId === nodeId) {
        setEditingNodeId(null);
        setSystemModalOpen(false);
      }
    },
    [editingNodeId, nodes]
  );

  /*
   * ---------------------------------------------------------
   * ADD SYSTEM
   * ---------------------------------------------------------
   */
  function handleAddSystem() {
    setEditingNodeId(null);
    setSystemModalOpen(true);
  }

  /*
   * ---------------------------------------------------------
   * SAVE SYSTEM
   * ---------------------------------------------------------
   */
  function handleSystemSubmit(
    data: SystemNodeData
  ) {
    if (editingNodeId) {
      setNodes((current) =>
        current.map((node) => {
          if (
            node.id !== editingNodeId
          ) {
            return node;
          }

          return {
            ...node,
            data: {
              ...data,
              id: node.id,
            },
          };
        })
      );
    } else {
      const id = crypto.randomUUID();

      const newSystem: EngineeringSystem = {
        ...data,
        id,
      };

      const newNode: ArchitectureNode = {
        id,
        type: "system",
        position: {
          x: 300,
          y: 200,
        },
        data: newSystem,
      };

      setNodes((current) => [
        ...current,
        newNode,
      ]);
    }

    setSystemModalOpen(false);
    setEditingNodeId(null);
  }

  /*
   * ---------------------------------------------------------
   * CONNECTION START
   * ---------------------------------------------------------
   */
  const onConnect: OnConnect = useCallback(
    (connection) => {
      if (
        !connection.source ||
        !connection.target
      ) {
        return;
      }

      setPendingConnection(connection);
      setConnectionModalOpen(true);
    },
    []
  );

  /*
   * ---------------------------------------------------------
   * CONNECTION LABEL
   * ---------------------------------------------------------
   */
  function getConnectionLabel(
    data: ConnectionData
  ) {
    const typeLabels: Record<
      ConnectionData["type"],
      string
    > = {
      power: "Power",
      communication: "Communication",
      sensor_data: "Sensor Data",
      control: "Control",
      mechanical: "Mechanical",
      thermal: "Thermal",
    };

    const typeLabel =
      typeLabels[data.type];

    return data.protocol
      ? `${typeLabel} · ${data.protocol}`
      : typeLabel;
  }

  /*
   * ---------------------------------------------------------
   * SAVE CONNECTION
   * ---------------------------------------------------------
   */
  function handleConnectionSubmit(
    data: ConnectionData
  ) {
    if (
      !pendingConnection ||
      !pendingConnection.source ||
      !pendingConnection.target
    ) {
      return;
    }

    const newEdge: ArchitectureEdge = {
      id: crypto.randomUUID(),
      source: pendingConnection.source,
      target: pendingConnection.target,
      sourceHandle:
        pendingConnection.sourceHandle,
      targetHandle:
        pendingConnection.targetHandle,
      label: getConnectionLabel(data),
      data,
    };

    setEdges((current) =>
      addEdge(newEdge, current)
    );

    setPendingConnection(null);
    setConnectionModalOpen(false);
  }

  /*
   * ---------------------------------------------------------
   * CURRENT EDITING NODE
   * ---------------------------------------------------------
   */
  const editingNode = editingNodeId
    ? nodes.find(
        (node) =>
          node.id === editingNodeId
      )
    : undefined;

  /*
   * ---------------------------------------------------------
   * CONNECTION NODES
   * ---------------------------------------------------------
   */
  const sourceNode =
    pendingConnection?.source
      ? nodes.find(
          (node) =>
            node.id ===
            pendingConnection.source
        )
      : undefined;

  const targetNode =
    pendingConnection?.target
      ? nodes.find(
          (node) =>
            node.id ===
            pendingConnection.target
        )
      : undefined;

  return (
    <div className="relative h-full w-full overflow-hidden bg-[#0b0d10]">
      {/* TOOLBAR */}

      <div className="absolute left-4 top-4 z-10 flex items-center gap-2">
        <button
          type="button"
          onClick={handleAddSystem}
          className="rounded-lg border border-white/10 bg-[#15191f] px-4 py-2 text-sm font-medium text-white shadow-lg transition hover:bg-[#1c2128]"
        >
          + Add System
        </button>

        <div className="rounded-lg border border-white/10 bg-[#15191f]/90 px-3 py-2 text-xs text-white/40 backdrop-blur">
          Drag systems · Connect handles
        </div>
      </div>

      {/* REACT FLOW */}

      <ReactFlow
        nodes={nodes}
        edges={edges}
        nodeTypes={nodeTypes}
        onNodesChange={onNodesChange}
        onEdgesChange={onEdgesChange}
        onConnect={onConnect}
        onNodeDoubleClick={(_, node) => {
          openSystemEditor(node.id);
        }}
        fitView
        fitViewOptions={{
          padding: 0.2,
        }}
        minZoom={0.2}
        maxZoom={2}
        defaultEdgeOptions={{
          animated: false,
        }}
        colorMode="dark"
        proOptions={{
          hideAttribution: true,
        }}
      >
        <Background />
        <Controls />

        <MiniMap
          pannable
          zoomable
          nodeColor="#3a424d"
        />
      </ReactFlow>

      {/* SYSTEM EDITOR */}

      <SystemModal
        open={systemModalOpen}
        initialData={
          editingNode
            ? editingNode.data
            : undefined
        }
        onClose={() => {
          setSystemModalOpen(false);
          setEditingNodeId(null);
        }}
        onSubmit={handleSystemSubmit}
      />

      {/* CONNECTION EDITOR */}

      <ConnectionModal
        open={connectionModalOpen}
        sourceName={
          sourceNode?.data.name ??
          "Unknown System"
        }
        targetName={
          targetNode?.data.name ??
          "Unknown System"
        }
        onClose={() => {
          setPendingConnection(null);
          setConnectionModalOpen(false);
        }}
        onSubmit={handleConnectionSubmit}
      />
    </div>
  );
}